window.DEEPDIVE=window.DEEPDIVE||{};window.DEEPDIVE["workflow-orchestration"]={"title":"工作流编排：用持久状态和确定性控制承载概率模型","subtitle":"从 DAG、状态机和持久执行，到幂等、重试、补偿、版本迁移与人工任务，建立可恢复、可审计的 AI 流程。","thesis":"当步骤和分支可预先描述时，流程控制应交给确定性编排器；LLM 是其中一个概率活动。可靠性来自<b>持久状态、幂等、超时和补偿</b>，不是让模型记住“做到哪”。","quality":{"contractVersion":2,"examples":[{"section":3,"evidence":{"setup":"发票抽取—校验—审批—入账","rule":"重复上传命中同一实例","steps":"入账超时先查状态","interpretation":"不表示未知副作用可直接重试"}}],"formulas":[{"id":"workflow-idempotency-key","section":4,"formulaIndex":1,"symbols":[{"name":"K","meaning":"业务系统用于识别重复活动请求的幂等键","evidence":"K 是业务去重使用的幂等键"},{"name":"workflowId","meaning":"当前持久工作流实例的唯一标识","evidence":"workflowId 标识流程实例"},{"name":"activityType","meaning":"当前副作用所属的活动种类","evidence":"activityType 标识活动种类"},{"name":"logicalAttempt","meaning":"同一业务意图在工作流中的逻辑尝试标识","evidence":"logicalAttempt 标识同一业务意图"}]}],"termReviews":[{"section":2,"reviewedAt":"2026-07-27","terms":[{"name":"DAG","meaning":"用无环有向边表示步骤依赖的任务图","purpose":"表达批处理和可并行的无环阶段","definitionEvidence":"DAG 表达无环依赖","purposeEvidence":"无环依赖、批处理、并行扇出"},{"name":"状态机","meaning":"用有限状态和条件转换描述流程生命周期","purpose":"表达循环、超时和人工暂停","definitionEvidence":"状态机表达条件循环","purposeEvidence":"条件、循环、超时、人工暂停"}]},{"section":6,"reviewedAt":"2026-07-27","terms":[{"name":"死信","meaning":"超过重试边界后等待人工或专门处理的失败任务队列","purpose":"隔离永久失败并避免无限重试","definitionEvidence":"进入死信/人工队列","purposeEvidence":"不能放任重试风暴"}]},{"section":7,"reviewedAt":"2026-07-27","terms":[{"name":"Saga","meaning":"用一系列局部事务和补偿动作协调长流程的模式","purpose":"在无法跨系统原子提交时恢复业务一致性","definitionEvidence":"跨系统事务靠补偿","purposeEvidence":"恢复跨系统一致性"}]}],"sectionContracts":[{"section":1,"definition":{"answer":"工作流编排由确定性控制器持久调度概率活动。","evidence":"工作流编排是由确定性控制器持久记录节点状态并调度概率活动的系统"},"problem":{"answer":"它解决 Agent 会话不能承担事务状态的问题。","evidence":"为什么“让 Agent 自己记住步骤”不是工作流"},"inputOutput":{"answer":"输入步骤依赖规则，输出可恢复流程实例。","evidence":"输入是可描述的步骤、依赖、schema 和恢复规则，输出是可重启、可审计的流程实例"},"mechanism":{"answer":"编排器记决定，LLM 只做局部概率活动。","evidence":"LLM 只负责局部判断"},"interpretation":{"answer":"固定路径应由工作流控制。","evidence":"固定路径用工作流"},"boundary":{"answer":"真正未知路径才使用受限 Agent。","evidence":"路径真正未知时才嵌入受限 Agent"}},{"section":2,"definition":{"answer":"DAG 状态机事件和 Agent 子流程表达不同控制结构。","evidence":"输出 DAG、状态机、事件驱动或 Agent 子流程"},"problem":{"answer":"它解决有条件循环为何不能只画成 DAG。","evidence":"为什么不能只画成 DAG"},"inputOutput":{"answer":"输入环等待事件未知性，输出控制模型。","evidence":"输入流程是否有环、等待、异步事件和未知路径，输出 DAG、状态机、事件驱动或 Agent 子流程"},"mechanism":{"answer":"无环用 DAG，条件循环用状态机，未知局部用 Agent。","evidence":"DAG 表达无环依赖，状态机表达条件循环"},"interpretation":{"answer":"四种模型可在同一系统组合。","evidence":"模型可组合但各自有复杂度"},"boundary":{"answer":"有条件循环硬塞 DAG 会失去清晰状态。","evidence":"会失去清晰状态"}},{"section":3,"definition":{"answer":"发票案例展示持久流程怎样从正确位置恢复。","evidence":"发票抽取—校验—审批—入账"},"problem":{"answer":"它处理抽取失败和入账超时后的继续策略。","evidence":"流程怎样从正确位置继续"},"inputOutput":{"answer":"输入文件 schema 校验审批 API，输出入账或暂停。","evidence":"输入文件、版本化发票 schema、校验规则、审批和财务 API，输出入账编号或带原因的暂停状态"},"mechanism":{"answer":"哈希去重局部重试持久等待，超时先查状态。","evidence":"入账超时先查状态"},"interpretation":{"answer":"恢复表示从已确认节点继续。","evidence":"恢复表示从已确认节点继续"},"boundary":{"answer":"它不表示未知副作用可直接重试。","evidence":"不表示未知副作用可直接重试"}},{"section":4,"definition":{"answer":"至少一次执行要求副作用使用稳定幂等键去重。","evidence":"至少一次执行意味着活动可能重复"},"problem":{"answer":"它解决重试让同一付款执行多次的问题。","evidence":"使同一活动可能执行多次"},"inputOutput":{"answer":"输入流程活动逻辑尝试，输出幂等键。","evidence":"输入流程 ID、活动类型和逻辑尝试，输出稳定幂等键"},"mechanism":{"answer":"用唯一键去重表和状态查询只保留一次业务效果。","evidence":"重复请求只产生一次业务效果"},"interpretation":{"answer":"长链一次成功率会随步骤数相乘下降。","evidence":"十步则0.99¹⁰≈90.44%"},"boundary":{"answer":"幂等不等于网络只传一次，也不修复错误参数。","evidence":"不等于网络只传一次"}},{"section":5,"definition":{"answer":"持久历史记录调度执行结果计时和审批事件。","evidence":"输入每次调度、开始、完成、失败、计时和审批事件"},"problem":{"answer":"它让进程崩溃后可重放决定而不重做副作用。","evidence":"重启变成重放决定，而非重做副作用"},"inputOutput":{"answer":"输入事件，输出可重放控制决定。","evidence":"输出重启后可重放的控制决定"},"mechanism":{"answer":"读取记录恢复，副作用用幂等和查询去重。","evidence":"业务活动靠幂等键和状态查询避免重做"},"interpretation":{"answer":"历史只证明系统记录了事件。","evidence":"历史证明系统记录了某个事件"},"boundary":{"answer":"未知外部结果仍需查询或人工。","evidence":"未知结果仍需查询或人工"}},{"section":6,"definition":{"answer":"重试策略按错误类型决定有界重试或升级。","evidence":"重试策略输入错误类型"},"problem":{"answer":"它避免永久错误被指数退避无限放大。","evidence":"指数退避能解决吗"},"inputOutput":{"answer":"输入错误次数时限，输出重试死信或停止。","evidence":"输入错误类型、尝试次数、退避和最大时限，输出重试、死信、人工处理或停止"},"mechanism":{"answer":"瞬态重试，永久错误修复，超限进入人工队列。","evidence":"超过阈值进入人工队列"},"interpretation":{"answer":"重试表示再次尝试而非错误已可恢复。","evidence":"指数退避不能让永久错误变瞬态"},"boundary":{"answer":"有界策略仍须防止重试风暴。","evidence":"不能放任重试风暴"}},{"section":7,"definition":{"answer":"补偿是失败后执行的新业务恢复动作。","evidence":"用新的业务动作恢复跨系统一致性"},"problem":{"answer":"它处理跨系统长流程无法原子回滚的问题。","evidence":"跨系统事务靠补偿，不是假装原子提交"},"inputOutput":{"answer":"输入副作用后续失败逆向动作，输出恢复或升级。","evidence":"输入已完成副作用、后续失败和预定义逆向动作，输出部分恢复、补偿失败或人工升级状态"},"mechanism":{"answer":"按成功副作用逆序执行预定义补偿并验证。","evidence":"为每个成功副作用预定义补偿"},"interpretation":{"answer":"补偿不是数据库原子回滚。","evidence":"而非数据库原子回滚"},"boundary":{"answer":"补偿会失败且有些动作不可逆。","evidence":"有些动作不可逆"}},{"section":8,"definition":{"answer":"版本迁移保护正在运行的旧工作流实例。","evidence":"版本迁移要保护正在运行的旧实例"},"problem":{"answer":"它避免新代码删除状态后旧历史无法重放。","evidence":"昨天启动的流程重放会怎样"},"inputOutput":{"answer":"输入历史代码 schema，输出兼容分支或迁移状态。","evidence":"输入运行中实例历史、工作流代码和活动 schema 版本，输出兼容分支或显式迁移后的状态"},"mechanism":{"answer":"相同历史保持相同决定，非确定值写入活动结果。","evidence":"相同历史得到相同控制决定"},"interpretation":{"answer":"快照回放降低不兼容风险。","evidence":"历史快照回放降低不兼容风险"},"boundary":{"answer":"它不能证明未来外部响应兼容。","evidence":"不能证明所有未来外部响应兼容"}},{"section":9,"definition":{"answer":"人工任务是可超时升级的持久等待状态。","evidence":"人工任务是可超时、可升级的持久状态"},"problem":{"answer":"它解决等待数天时流程怎样不丢失不永久卡死。","evidence":"怎样不丢失也不永久卡死"},"inputOutput":{"answer":"输入负责人证据 SLA 路径，输出审批或超时事件。","evidence":"输入负责人资格、证据、SLA、提醒和升级路径，输出批准、拒绝、超时升级或取消事件"},"mechanism":{"answer":"释放进程并用任务令牌等待外部批准恢复。","evidence":"用任务令牌在外部事件到达后恢复"},"interpretation":{"answer":"持久等待不表示可以无限悬挂。","evidence":"不表示审批可无限期悬挂"},"boundary":{"answer":"超时不能自动通过，敏感理由受保留策略。","evidence":"超时不能静默自动通过"}},{"section":10,"definition":{"answer":"恢复评测用故障注入验证流程从正确节点继续。","evidence":"恢复评测输入理想任务与崩溃"},"problem":{"answer":"它解决理想路径全通过为何仍不能上线的问题。","evidence":"为什么仍不能上线"},"inputOutput":{"answer":"输入任务和六类故障，输出恢复与副作用指标。","evidence":"输入理想任务与崩溃、丢包、重复回调、旧 schema、补偿失败和队列满载故障，输出端到端成功、重复副作用、补偿、积压、SLA 与恢复节点"},"mechanism":{"answer":"注入故障后用事件历史核对恢复位置和真实副作用。","evidence":"事件历史用于核对是否从正确位置继续"},"interpretation":{"answer":"一次理想路径通过不能代表恢复可靠。","evidence":"一次理想路径通过不能代表可上线"},"boundary":{"answer":"故障注入只覆盖已设计的故障场景。","evidence":"故障注入也只覆盖已设计场景"}},{"section":12,"definition":{"answer":"概率活动重放读取历史结果而不重新生成。","evidence":"概率活动的结果必须入历史"},"problem":{"answer":"它避免恢复时同一模型输出变化导致另一分支。","evidence":"为什么可能走向另一个分支"},"inputOutput":{"answer":"输入模型版本输出校验历史，输出相同控制分支。","evidence":"输入已记录的模型输入版本、模型版本、输出和校验结果，输出相同历史下相同的控制分支"},"mechanism":{"answer":"旧历史读旧结果，新尝试才创建新活动事件。","evidence":"显式新尝试才创建新事件"},"interpretation":{"answer":"结果确定性来自历史记录而非模型本身。","evidence":"恢复时读取旧结果而不再次生成"},"boundary":{"answer":"缓存键缺版本会把过期答案伪装成确定性。","evidence":"旧答案会被伪装成确定性"}}]},"html":"\n        <div class=\"dd-goals\"><b>读完你应该能：</b>区分 DAG、状态机与自主 Agent；推导至少一次执行下的幂等要求；设计补偿和人工暂停；用故障注入验证恢复与版本迁移。</div>\n        \n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">1</span>确定性骨架把概率错误关在可观察节点<span class=\"dd-badge intuition\">定位</span></h2><p class=\"dd-lead\">为什么“让 Agent 自己记住步骤”不是工作流？</p><p>Agent 会话可能中断、压缩或改变计划，不能承担事务状态。编排器持久记录每个节点的输入、状态、尝试次数和输出，负责依赖、超时与恢复；LLM 节点只完成分类、抽取、生成或判断，并以版本化schema交付。固定路径用工作流，自主搜索只放在真正未知的局部。</p><p>工作流编排是由确定性控制器持久记录节点状态并调度概率活动的系统。输入是可描述的步骤、依赖、schema 和恢复规则，输出是可重启、可审计的流程实例。编排器保存事实和决定，LLM 只负责局部判断；路径真正未知时才嵌入受限 Agent，不能让模型上下文承担事务状态。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">2</span>DAG 与状态机表达不同控制结构<span class=\"dd-badge eng\">模型</span></h2><p class=\"dd-lead\">有条件循环的审核流程为什么不能只画成 DAG？</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>模型</th><th>适合</th><th>限制</th></tr></thead><tbody><tr><td>DAG</td><td>无环依赖、批处理、并行扇出</td><td>循环/等待表达笨重</td></tr><tr><td>状态机</td><td>条件、循环、超时、人工暂停</td><td>分支多时复杂</td></tr><tr><td>事件驱动</td><td>跨系统异步反应</td><td>顺序和重复更难追踪</td></tr><tr><td>Agent子流程</td><td>路径事先未知</td><td>成本和终止不确定</td></tr></tbody></table></div><p>同一系统可用DAG组织大阶段、状态机管理订单生命周期、事件触发外部回调，并在某个节点调用受限Agent。</p><p>控制模型选择输入流程是否有环、等待、异步事件和未知路径，输出 DAG、状态机、事件驱动或 Agent 子流程。DAG 表达无环依赖，状态机表达条件循环，事件驱动接收外部变化，Agent 处理局部未知。模型可组合但各自有复杂度；把有条件循环硬塞进 DAG 会失去清晰状态。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">3</span>完整示例：发票抽取—校验—审批—入账<span class=\"dd-badge eng\">案例推演</span></h2><p class=\"dd-lead\">LLM抽取失败或入账超时后，流程怎样从正确位置继续？</p><ol class=\"dd-steps\"><li><b>接收：</b>以文件哈希作为流程ID，重复上传命中同一实例。</li><li><b>抽取：</b>LLM输出版本化invoice schema；解析失败只重试该活动。</li><li><b>校验：</b>确定性代码检查金额合计、供应商和重复发票。</li><li><b>审批：</b>高金额进入持久人工任务，等待数天也不占工作进程。</li><li><b>入账：</b>调用财务API并携带幂等键 <code>invoice_id</code>。</li><li><b>通知：</b>只有确认入账编号后发送；若通知失败可独立重试。</li></ol><p>流程重启后读取持久历史，不重复已确认活动。若入账结果未知，先查询财务系统，再决定重试或人工调查。</p><p>发票案例输入文件、版本化发票 schema、校验规则、审批和财务 API，输出入账编号或带原因的暂停状态。流程用哈希去重，抽取失败只重试该节点，人工审批持久等待，入账超时先查状态。恢复表示从已确认节点继续，不表示未知副作用可直接重试。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">4</span>至少一次执行意味着活动可能重复<span class=\"dd-badge math\">执行语义</span></h2><p class=\"dd-lead\">三步流程每步99%可靠，整条一次成功概率是多少？</p><p>若三个独立步骤各自一次成功率0.99，整条无重试成功率为0.99³≈<b>97.03%</b>；十步则0.99¹⁰≈90.44%。重试提高最终成功，却使同一活动可能执行多次，因此副作用必须幂等。</p><div class=\"dd-formula\" data-formula-id=\"workflow-idempotency-key\" data-display=\"mathml\"><math display=\"block\" aria-label=\"幂等键 K 由流程标识、活动类型和逻辑尝试标识组成\"><mi>K</mi><mo>=</mo><mi>workflowId</mi><mo>∥</mo><mi>activityType</mi><mo>∥</mo><mi>logicalAttempt</mi></math></div><p class=\"dd-formula-note\"><code>K</code> 是业务去重使用的幂等键；<code>workflowId</code> 标识流程实例，<code>activityType</code> 标识活动种类，<code>logicalAttempt</code> 标识同一业务意图。符号 ∥ 表示按无歧义编码拼接，不是数值相加。</p><p>“精确一次”通常是业务效果而非网络传输保证：通过唯一键、去重表和状态查询，使重复请求只产生一次付款/写入。</p><p>至少一次执行输入流程 ID、活动类型和逻辑尝试，输出稳定幂等键并让重复请求只产生一次业务效果。独立步骤成功率相乘说明长链一次成功率下降，重试提高可用性却制造重复执行。幂等保证针对定义好的业务键，不等于网络只传一次，也不能修复错误业务参数。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">5</span>原创图：持久历史把重启变成重放决定，而非重做副作用<span class=\"dd-badge intuition\">可视化</span></h2><p class=\"dd-lead\">进程崩溃后，编排器怎样知道哪些步骤已经完成？</p><figure class=\"dd-fig\"><svg viewBox=\"0 0 735 325\" role=\"img\" aria-label=\"工作流编排器把决定写入持久历史并调度幂等活动，失败重试与补偿、人工等待都从历史恢复\"><defs><marker id=\"wf28\" markerWidth=\"8\" markerHeight=\"8\" refX=\"6\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 z\" fill=\"#788293\"/></marker></defs><rect x=\"20\" y=\"105\" width=\"140\" height=\"100\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"90\" y=\"134\" text-anchor=\"middle\" class=\"svg-t\">编排器</text><text x=\"90\" y=\"159\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">依赖 · 分支 · 超时</text><text x=\"90\" y=\"182\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">只做确定性决定</text><path d=\"M160,155 L210,155\" stroke=\"#788293\" marker-end=\"url(#wf28)\"/><rect x=\"215\" y=\"75\" width=\"160\" height=\"160\" rx=\"9\" fill=\"#21252d\" stroke=\"#8b76bd\"/><text x=\"295\" y=\"105\" text-anchor=\"middle\" class=\"svg-t\">持久事件历史</text><text x=\"295\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">Scheduled / Started</text><text x=\"295\" y=\"155\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">Completed / Failed</text><text x=\"295\" y=\"178\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">Timer / Approval</text><text x=\"295\" y=\"207\" text-anchor=\"middle\" class=\"svg-t\">重启后重放决定</text><path d=\"M375,125 L430,70\" stroke=\"#788293\" marker-end=\"url(#wf28)\"/><path d=\"M375,155 L430,155\" stroke=\"#788293\" marker-end=\"url(#wf28)\"/><path d=\"M375,185 L430,240\" stroke=\"#788293\" marker-end=\"url(#wf28)\"/><rect x=\"435\" y=\"35\" width=\"140\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#65a6d9\"/><text x=\"505\" y=\"62\" text-anchor=\"middle\" class=\"svg-t\">LLM 活动</text><text x=\"505\" y=\"84\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">schema输出 · 可重试</text><rect x=\"435\" y=\"120\" width=\"140\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#72b293\"/><text x=\"505\" y=\"147\" text-anchor=\"middle\" class=\"svg-t\">业务副作用</text><text x=\"505\" y=\"169\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">幂等键 · 状态查询</text><rect x=\"435\" y=\"205\" width=\"140\" height=\"70\" rx=\"9\" fill=\"#21252d\" stroke=\"#cf7c72\"/><text x=\"505\" y=\"232\" text-anchor=\"middle\" class=\"svg-t\">人工 / 外部事件</text><text x=\"505\" y=\"254\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">持久等待 · SLA</text><path d=\"M575,70 L625,70\" stroke=\"#788293\" marker-end=\"url(#wf28)\"/><path d=\"M575,155 L625,155\" stroke=\"#788293\" marker-end=\"url(#wf28)\"/><path d=\"M575,240 L625,240\" stroke=\"#788293\" marker-end=\"url(#wf28)\"/><rect x=\"630\" y=\"72\" width=\"87\" height=\"166\" rx=\"9\" fill=\"#21252d\" stroke=\"#d3a05a\"/><text x=\"673\" y=\"105\" text-anchor=\"middle\" class=\"svg-t\">结果</text><text x=\"673\" y=\"132\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">完成</text><text x=\"673\" y=\"155\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">重试</text><text x=\"673\" y=\"178\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">补偿</text><text x=\"673\" y=\"201\" text-anchor=\"middle\" class=\"svg-t\" font-size=\"11\">升级</text></svg><figcaption>图 1　历史记录的是事实和决定；恢复时重放控制逻辑，外部副作用靠幂等与查询避免重复。</figcaption></figure><p>持久历史输入每次调度、开始、完成、失败、计时和审批事件，输出重启后可重放的控制决定。编排器读取已记录结果恢复，业务活动靠幂等键和状态查询避免重做。历史证明系统记录了某个事件，不自动证明外部系统事实真实，未知结果仍需查询或人工。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">6</span>重试只适合瞬态失败，且必须有边界<span class=\"dd-badge eng\">错误处理</span></h2><p class=\"dd-lead\">LLM持续输出非法字段，指数退避能解决吗？</p><p>网络超时、限流和短暂不可用可按错误类型重试；schema不兼容、权限拒绝和业务校验失败需要修数据、迁移或人工处理。设置最大尝试、指数退避和抖动，超过阈值进入死信/人工队列；不要让重试风暴放大下游故障。</p><p>每次尝试保留同一逻辑活动ID和不同物理尝试号，便于去重和诊断。</p><p>重试策略输入错误类型、尝试次数、退避和最大时限，输出重试、死信、人工处理或停止。网络超时和限流可有界重试，schema、权限和业务规则错误必须修复。超过阈值进入人工队列；指数退避不能让永久错误变瞬态，也不能放任重试风暴。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">7</span>跨系统事务靠补偿，不是假装原子提交<span class=\"dd-badge eng\">Saga</span></h2><p class=\"dd-lead\">已预订酒店但支付失败，工作流怎样回到一致状态？</p><p>长流程无法锁住多个外部系统。为每个成功副作用预定义补偿：取消预订、退回库存、撤销草稿；补偿本身也会失败，需要幂等、重试和人工升级。并非所有动作可逆，例如已发送邮件只能追加更正，因此设计时先减小不可逆步骤并尽量后置。</p><div class=\"dd-note warn\"><b>初学者最易混淆：</b>工作流“最终完成”不等于数据库式全有或全无；必须显式定义部分完成、未知和补偿失败状态。</div><p>补偿机制输入已完成副作用、后续失败和预定义逆向动作，输出部分恢复、补偿失败或人工升级状态。它用新的业务动作恢复跨系统一致性，而非数据库原子回滚。补偿本身会失败且有些动作不可逆，所以不可逆步骤应减小并后置。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">8</span>版本迁移要保护正在运行的旧实例<span class=\"dd-badge eng\">演进</span></h2><p class=\"dd-lead\">新代码删除了一个状态，昨天启动的流程重放会怎样？</p><p>工作流定义和活动schema版本化；旧实例继续使用兼容分支或经显式迁移转换状态。确定性重放要求相同历史得到相同控制决定，不能让当前时间、随机数或外部查询直接影响编排逻辑；这些非确定值应作为活动结果写入历史。</p><p>发布前用生产历史快照重放新代码，发现不兼容再灰度。</p><p>版本迁移输入运行中实例历史、工作流代码和活动 schema 版本，输出兼容分支或显式迁移后的状态。重放必须让相同历史得到相同控制决定，时间、随机数和外部查询写成活动结果。历史快照回放降低不兼容风险，但不能证明所有未来外部响应兼容。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">9</span>人工任务是可超时、可升级的持久状态<span class=\"dd-badge eng\">人在回路</span></h2><p class=\"dd-lead\">审批等待三天时，流程怎样不丢失也不永久卡死？</p><p>审批节点保存负责人、资格、证据、SLA、提醒和升级路径；进程可释放资源，外部批准事件用任务令牌恢复。超时可升级、拒绝或取消，不能静默自动通过。审核结果和理由进入历史，但敏感反馈按保留策略处理。</p><p>人工任务输入负责人资格、证据、SLA、提醒和升级路径，输出批准、拒绝、超时升级或取消事件。流程释放工作进程并用任务令牌在外部事件到达后恢复。等待持久化不表示审批可无限期悬挂，超时不能静默自动通过，敏感理由仍受保留策略约束。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">10</span>评测要注入崩溃、重复和不确定结果<span class=\"dd-badge eng\">验证</span></h2><p class=\"dd-lead\">理想路径全部通过，为什么仍不能上线？</p><p>报告端到端成功、节点失败与重试、重复副作用、补偿成功、未知状态、队列积压、等待/执行时间、每成功任务成本和人工SLA。故障注入包括活动完成后回包丢失、编排器重启、外部回调重复、旧schema、补偿失败和队列满载。</p><p>通过事件历史验证恢复从正确节点继续，并比较“确定性主干+LLM节点”与全Agent方案的质量、成本和可诊断性。</p><p>恢复评测输入理想任务与崩溃、丢包、重复回调、旧 schema、补偿失败和队列满载故障，输出端到端成功、重复副作用、补偿、积压、SLA 与恢复节点。事件历史用于核对是否从正确位置继续。一次理想路径通过不能代表可上线，故障注入也只覆盖已设计场景。</p></section>\n      <section class=\"dd-sec\" data-section-role=\"reference\"><h2><span class=\"dd-n\">11</span>常见误区与学习路线<span class=\"dd-badge intuition\">误区与依赖</span></h2><p class=\"dd-lead\">工作流的价值不是画流程图，而是失败后仍知道真实状态。</p><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>误区</th><th>更准确的理解</th></tr></thead><tbody><tr><td>工作流就是顺序调用</td><td>还需持久状态、恢复和执行语义</td></tr><tr><td>重试可解决所有错误</td><td>永久错误需迁移、修复或人工</td></tr><tr><td>消息只会到达一次</td><td>至少一次下必须幂等和去重</td></tr><tr><td>补偿等于回滚</td><td>是新的业务动作，也可能失败</td></tr><tr><td>LLM可记住流程状态</td><td>模型上下文不是事务日志</td></tr></tbody></table></div><div class=\"dd-table-wrap\"><table class=\"dd-table\"><thead><tr><th>层级</th><th>依赖与延伸</th></tr></thead><tbody><tr><td>先修</td><td>状态机、分布式系统、API契约</td></tr><tr><td><b>本页核心</b></td><td>持久历史、幂等、重试、补偿、版本</td></tr><tr><td>相邻</td><td>Agent循环、多智能体、人在回路</td></tr><tr><td>工程</td><td>事件溯源、死信、故障注入、SLA</td></tr></tbody></table></div></section>\n      <section class=\"dd-sec\" data-section-role=\"core\"><h2><span class=\"dd-n\">12</span>概率活动的结果必须入历史，不能在重放时重新生成<span class=\"dd-badge eng\">确定性重放</span></h2><p class=\"dd-lead\">恢复流程时再次调用同一模型，为什么可能走向另一个分支？</p><p>模型、温度、服务版本和随机性会使同一输入产生不同输出。编排器第一次调用后把输入版本、模型版本、输出和校验结果写入历史；重放控制逻辑时读取已记录结果，不再次生成。只有显式的新尝试才产生新活动事件，并保留旧结果用于审计。</p><p>对可缓存的只读活动使用内容哈希，但缓存键必须包含提示、模型、工具与数据版本；否则“重用旧答案”会把过期事实伪装成确定性。</p><p>概率活动重放输入已记录的模型输入版本、模型版本、输出和校验结果，输出相同历史下相同的控制分支。恢复时读取旧结果而不再次生成，显式新尝试才创建新事件。内容哈希缓存也必须包含提示、模型、工具和数据版本，否则旧答案会被伪装成确定性。</p></section>\n        <section class=\"dd-sec\" data-section-role=\"synthesis\"><h2><span class=\"dd-n\">13</span>把因果链连起来<span class=\"dd-badge intuition\">综合</span></h2><p class=\"dd-lead\">这个概念怎样从问题一路连接到可验证的实践？</p><ol class=\"dd-chain\"><li>把任务画成依赖与状态转换</li><li>定义版本化输入输出schema</li><li>标注副作用、幂等键和补偿</li><li>由编排器持久记录决定</li><li>工作者执行LLM或业务活动</li><li>按错误类型重试或升级</li><li>人工/外部事件持久等待</li><li>故障恢复、历史重放与版本迁移</li></ol></section>\n        <section class=\"dd-sec\" data-section-role=\"assessment\"><h2><span class=\"dd-n\">14</span>误区与自测<span class=\"dd-badge intuition\">自测</span></h2><p class=\"dd-lead\">你能否不用背术语，解释它的机制、边界与验证方法？</p><div class=\"dd-quiz\"><ol><li>为什么LLM不应保存工作流状态？</li><li>至少一次执行为何要求幂等？</li><li>补偿与数据库回滚有何不同？</li><li>哪些错误不该重试？</li><li>怎样验证恢复能力？</li><li>假设“工作流编排：用持久状态和确定性控制承载概率模型”在离线示例上表现正常、上线后核心结果却下降，你会怎样按输入、内部变换、输出反馈和适用边界定位问题？</li></ol></div><details class=\"dd-answers\"><summary>参考答案</summary><ol><li>上下文可丢失或变化，事务状态需要持久、可重放的记录。</li><li>超时和重试可能让同一活动执行多次，业务效果必须去重。</li><li>补偿是新的业务动作，可能不完全逆转且自身会失败。</li><li>权限、schema、业务规则等永久错误应修复、迁移或人工处理。</li><li>注入崩溃、丢包、重复回调和补偿失败，检查历史重放与真实副作用。</li><li>先保存同一失败样本及环境，确认输入、权限和前置条件没有漂移；再记录关键中间状态，检查机制是否按本页描述完成变换；随后把原始输出与独立指标、人工终验对照；最后用边界样例和对照实验复测。只有定位到首次偏离预期的环节，才能判断应修改数据、机制、评测还是使用边界。</li></ol></details></section>\n        <div class=\"dd-src\"><b>资料来源与改编说明</b><ul><li><a href=\"https://www.omg.org/spec/BPMN/2.0/\" target=\"_blank\" rel=\"noopener\">BPMN 2.0</a>：业务流程建模标准</li><li><a href=\"https://docs.temporal.io/temporal\" target=\"_blank\" rel=\"noopener\">Temporal Durable Execution</a>：事件历史与持久执行概念</li><li><a href=\"https://www.cs.cornell.edu/andru/cs711/2002fa/reading/sagas.pdf\" target=\"_blank\" rel=\"noopener\">Saga Pattern</a>：长事务与补偿</li></ul><div class=\"dd-src-date\">访问日期：2026-07-22</div></div>"};
